('conversation-conv-treffen', 'conversation-def', $json${"sid":"conv-treffen","title":"Verabredung","titleEn":"Making plans","emoji":"🎬","ctx":"Social plans","band":"A1-A2","closing":"Perfekt, bis dann!","variants":[{"id":"treffen-kino","name":"Kinoabend","steps":[{"n":"Heute läuft endlich der neue Film!","nEn":"The new movie is finally showing today!","p":"Ask if she wants to come along tomorrow.","opts":[{"ref":"Kommst du morgen mit?","ok":true},{"ref":"Ich muss mich beeilen.","fb":"Slow down - talk about the movie plan!"}]},{"n":"Morgen? Ja, gern! Wann und wo treffen wir uns?","nEn":"Tomorrow? Yes, sure! When and where do we meet?","p":"Propose eight o'clock in front of the cinema.","opts":[{"ref":"Wir treffen uns um acht vor dem Kino.","ok":true},{"ref":"Ich warte vor dem Eingang auf dich.","fb":"Right place - but give her a TIME too!"}]},{"n":"Um acht passt perfekt.","nEn":"Eight works perfectly.","p":"Say you will wait at the entrance.","opts":[{"ref":"Ich warte vor dem Eingang auf dich.","ok":true},{"ref":"Ich muss mich für den Kurs anmelden.","fb":"Registration tomorrow - tonight is movie night!"}]}]},{"id":"treffen-essen","name":"Gemeinsam essen","steps":[{"n":"Soll ich für uns beide kochen?","nEn":"Should I cook for the both of us?","p":"Suggest going out to eat together instead.","opts":[{"ref":"Wollen wir heute zusammen essen gehen?","ok":true},{"ref":"Zahlen Sie mit Karte oder bar?","fb":"Payment comes AFTER dinner!"}]},{"n":"Gute Idee! Ich kenne ein neues italienisches Restaurant.","nEn":"Good idea! I know a new Italian restaurant.","p":"Say you are looking forward to it.","opts":[{"t":"Super, ich freue mich!","en":"Great, I am looking forward to it!","ne":"राम्रो, म खुसी छु!","neR":"raamro ma khusi chhu","ok":true},{"ref":"Ich muss mich an das neue Umfeld gewöhnen.","fb":"New places take time - but stay positive!"}]}]},{"id":"treffen-kaffee","name":"Auf einen Kaffee","steps":[{"n":"Puh, was für ein Tag...","nEn":"Phew, what a day...","p":"Invite your 