('conversation-conv-alltag', 'conversation-def', $json${"sid":"conv-alltag","title":"Tagesablauf","titleEn":"Daily routine","emoji":"⏰","ctx":"Daily routine","band":"A1","closing":"Mach's gut!","variants":[{"id":"alltag-wache","name":"Morgens aufstehen","steps":[{"n":"Ich stehe um sieben Uhr auf.","nEn":"I get up at seven o'clock.","p":"What time do you get up?","opts":[{"ref":"Ich stehe um sechs Uhr auf.","ok":true},{"t":"Ich habe heute viel gearbeitet.","en":"I worked a lot today.","ne":"मैले आज धेरै काम गरें।","neR":"maile aaja dherai kaam garen","fb":"That was yesterday!"}]},{"n":"Und was machst du am Wochenende?","nEn":"And what are you doing this weekend?","p":"Say you are looking forward to the weekend.","opts":[{"ref":"Ich freue mich auf das Wochenende.","ok":true},{"ref":"Ich rufe dich morgen an.","fb":"Calling plans don't match this!"}]}]},{"id":"alltag-beerben","name":"Sich beeilen","steps":[{"n":"Pass auf - wir müssen uns beeilen!","nEn":"Watch out - we need to hurry!","p":"Agree and say you will come along.","opts":[{"t":"Okay, ich komme gleich mit.","en":"Okay, I'm coming right along.","ne":"ठीक छ, म बिझैं साथैं।","neR":"thik cha ma bizhain sathain","ok":true},{"ref":"Ich warte vor dem Eingang auf dich.","fb":"Not at the cinema now - hurry first!"}]},{"n":"Schön, dass du mitkommst!","nEn":"Nice that you're coming along!","p":"Say you will call the next day.","opts":[{"ref":"Ich rufe dich morgen an.","ok":true},{"ref":"Ich steige an der nächsten Haltestelle aus.","fb":"Wrong transport - stay on the call!"}]}]}]}$json$::jsonb, 7),
('conversation-conv-nachfragen', 'conversation-def', $json${"sid":"conv-nachfragen","title":"Hören & Nachfragen","titleEn":"Listening & asking","emoji":"👂","ctx":"Asking others","band":"A1-A2","closing":"Danke, alles klar!","variants":[{"id":"nachfragen-langsam","name":"Langsamer bitte","steps":[{"n":"Entschuldigung, ich habe nicht alles verstanden.","nEn":"Excuse me, I didn't understand everything.","p":"Politely ask them to speak more slowly.","opts":[{"t":"Können Sie das bitte langsamer sagen?","en":"Could you please say that more slowly?","ne":"के तपाईंले यो बिचार ढिलो बोलेर भन्न सक्नुहुन्छ?","neR":"ke tapaaileyo bichar dhilo bolera bhanna saknunuhunchha","ok":true},{"ref":"Wo ist bitte der Bahnhof?","fb":"Different question needed - ask about the speed!"}]},{"n":"Ja, natürlich! Nochmals?","nEn":"Yes, of course! Once more?","p":"Repeat your request in a friendly way.","opts":[{"ref":"Können Sie bitte langsamer sprechen?","ok":true},{"ref":"Zahlen Sie mit Karte oder bar?","fb":"Wrong topic - repeat the speed request!"}]}]},{"id":"nachfragen-wiederholen","name":"Nochmal bitte","steps":[{"n":"Was haben Sie gesagt?","nEn":"What did you say?","p":"Politely ask for repetition.","opts":[{"t":"Könnten Sie das noch einmal wiederholen?","en":"Could you repeat that once more?","ne":"के तपाईंले यो आफ्नैले एकपटक ढिलो बोलेर दोहोर्याउन सक्नुहुन्छ?","neR":"ke tapaaileyo aaphnailae ekapataka dhilo bolera dohoryau saknunuhunchha","ok":true},{"ref":"Sprechen Sie Englisch?","fb":"That's a different language - ask to repeat!"}]},{"n":"Klar, hier noch einmal langsamer: ...","nEn":"Clear, here once more more slowly: ...","p":"Thank them for repeating.","opts":[{"t":"Vielen Dank, das hilft mir sehr!","en":"Thank you very much, that helps me a lot!","ne":"धेरै धन्यवाद, यो ले मलाई धेरै मद्दत गर्छ!","neR":"dherai dhanyabaad, yo lae malai dherai maddat garchha","ok":true},{"ref":"Ich rufe dich morgen an.","fb":"Not about calling - thank for repeating!"}]}]}]}$json$::jsonb, 8)
